  const samples=Array.from({length:102},()=>event({applicationId,environmentId,source:'SERVER',category:'BACKEND',severity:'ERROR',eventCode:'workspace.failed',normalizedMessage:'Workspace retained failure',tenantReference:'workspace-a',releaseVersion:'v1'}));samples.push(event({...samples[0],eventId:randomUUID(),tenantReference:'workspace-b'}),event({...samples[0],eventId:randomUUID(),tenantReference:undefined}));
