  const engine=new IssueEngine(database,registry);for(let jobs=await engine.queue.claim(randomUUID(),50,['AGGREGATE']);jobs.length;jobs=await engine.queue.claim(randomUUID(),50,['AGGREGATE']))for(const job of jobs)await engine.aggregate(job);
  const monitor=new MonitoringEngine(database,registry);await monitor.configure(root,applicationId,{code:'ERROR_BURST',enabled:true,threshold:1,minimum_samples:1,window_seconds:300,cooldown_seconds:600,reason:'Workspace bounded fixture rule'});await monitor.evaluate(500);
  const ops=new OperationsService(database,registry),target={applicationId,environmentId,tenantReference:'workspace-a'},foreign={...target,tenantReference:'workspace-b'},none={applicationId,environmentId,tenantReference:null};
  const incident=(await ops.list(root,target,'incidents')).items[0],foreignIncident=(await ops.list(root,foreign,'incidents')).items[0],noneIncident=(await ops.list(root,none,'incidents')).items[0];expect(incident).toBeDefined();expect(foreignIncident).toBeDefined();expect(noneIncident).toBeDefined();
