  const job=await claim(service,app,env);expect(await service.execute({...job,application_id:appB,environment_id:envB},2)).toBe(false);expect(await service.execute(job,2)).toBe(true);expect(await service.execute(job,2)).toBe(false);
  const rows=await database.worker(async c=>(await c.query('SELECT event_id,environment_id FROM observability.events WHERE application_id=$1 ORDER BY event_id',[app])).rows);expect(rows.some(row=>row.event_id===old.eventId&&row.environment_id===env)).toBe(false);expect(rows.some(row=>row.event_id===old.eventId&&row.environment_id===otherEnv)).toBe(true);expect(rows.some(row=>row.event_id===pending.eventId&&row.environment_id===env)).toBe(true);expect(rows.some(row=>row.event_id===fresh.eventId)).toBe(true);
